import {
  describe,
  it,
  expect,
  beforeAll,
  afterAll,
  beforeEach,
} from "bun:test";
import { appRouter } from "@/server/trpc/router";
import { createTRPCContext } from "@/server/trpc/trpc";
import { prisma } from "@/lib/prisma";
import type { AppSession } from "@/lib/auth/session";

/**
 * "Generar desde stock bajo", and what counts as already covered.
 *
 * The procedure skipped a product only when that product was already on its
 * **own** auto-generated list. So anything somebody had written on a list of
 * their own was offered again here, and pressing the button quietly
 * duplicated the week's shop.
 *
 * It was also a third definition of "already covered" — the kitchen has one,
 * `getStockOverview` has one, and this had its own — which is the exact
 * duplication `src/lib/stock/low-stock.ts` was extracted to end. It asks
 * `needsMoreOnList` now, like the kitchen's button does.
 */

const A = { userId: "", householdId: "", productId: "", manualListId: "" };

async function caller() {
  const session: AppSession = {
    user: {
      id: A.userId,
      email: `${A.userId}@example.com`,
      name: "Generate",
      householdId: A.householdId,
      role: "OWNER",
    },
    expires: new Date(Date.now() + 3600 * 1000).toISOString(),
    expiresKind: "idle",
    sessionId: crypto.randomUUID(),
  };
  return appRouter.createCaller(await createTRPCContext({ session }));
}

/** The auto list's unticked rows for the one product, newest state. */
async function autoRows() {
  return prisma.shoppingItem.findMany({
    where: {
      productId: A.productId,
      shoppingList: { householdId: A.householdId, isAutoGenerated: true },
    },
  });
}

beforeAll(async () => {
  const household = await prisma.household.create({
    data: { name: "Generate household" },
  });
  const user = await prisma.user.create({
    data: {
      email: `generate-${Date.now()}@example.com`,
      name: "Generate",
      householdId: household.id,
      role: "OWNER",
    },
  });
  const product = await prisma.product.create({
    data: {
      name: "Leche entera",
      defaultUnit: "L",
      minStock: 2,
      householdId: household.id,
    },
  });
  const manual = await prisma.shoppingList.create({
    data: { name: "La mía", householdId: household.id },
  });

  Object.assign(A, {
    userId: user.id,
    householdId: household.id,
    productId: product.id,
    manualListId: manual.id,
  });
});

beforeEach(async () => {
  // No stock at all, and nothing written down, unless a test says otherwise.
  await prisma.shoppingItem.deleteMany({
    where: { shoppingList: { householdId: A.householdId } },
  });
  await prisma.shoppingList.deleteMany({
    where: { householdId: A.householdId, isAutoGenerated: true },
  });
  await prisma.stockEntry.deleteMany({ where: { productId: A.productId } });
});

afterAll(async () => {
  await prisma.shoppingItem.deleteMany({
    where: { shoppingList: { householdId: A.householdId } },
  });
  await prisma.shoppingList.deleteMany({
    where: { householdId: A.householdId },
  });
  await prisma.stockEntry.deleteMany({ where: { productId: A.productId } });
  await prisma.product.deleteMany({ where: { householdId: A.householdId } });
  await prisma.user.deleteMany({ where: { id: A.userId } });
  await prisma.household.deleteMany({ where: { id: A.householdId } });
  await prisma.$disconnect();
});

async function writeOnManualList(
  quantity: number,
  isChecked = false,
  unit?: string,
) {
  await prisma.shoppingItem.create({
    data: {
      shoppingListId: A.manualListId,
      productId: A.productId,
      quantity,
      isChecked,
      unit,
    },
  });
}

describe("generateFromLowStock", () => {
  it("writes down what nothing covers", async () => {
    const api = await caller();
    await api.shopping.generateFromLowStock();

    const rows = await autoRows();
    expect(rows).toHaveLength(1);
    // 1.5× a minimum of 2 is the target, and nothing counts towards it yet.
    expect(rows[0]?.quantity).toBe(3);
  });

  it("leaves alone what another list already covers", async () => {
    await writeOnManualList(3);

    const api = await caller();
    await api.shopping.generateFromLowStock();

    // The defect: the product was on somebody's own list, this looked only at
    // its own, and the household was told to buy three litres of milk twice.
    expect(await autoRows()).toHaveLength(0);
  });

  it("does not count an amount in another unit as covering the minimum", async () => {
    // Milk is counted in litres; 500 millilitres written down is not 500 L.
    await writeOnManualList(500, false, "ml");

    const api = await caller();
    await api.shopping.generateFromLowStock();

    const rows = await autoRows();
    expect(rows).toHaveLength(1);
    expect(rows[0]?.quantity).toBe(3);
  });

  it("stores an item added in a convertible unit in the product's", async () => {
    const product = await prisma.product.create({
      data: {
        name: "Huevos",
        defaultUnit: "unidad",
        householdId: A.householdId,
      },
    });
    const api = await caller();

    const item = await api.shopping.addItem({
      idempotencyKey: crypto.randomUUID(),
      composedByUserId: A.userId,
      shoppingListId: A.manualListId,
      productId: product.id,
      quantity: 3,
      unit: "uds",
    });

    // "uds" is the product's unit by another name; stored as typed, it would
    // not count towards what the lists cover.
    expect(item.unit).toBe("unidad");
    expect(item.quantity).toBe(3);
  });

  it("counts a ticked row as bought, not as covered", async () => {
    await writeOnManualList(3, true);

    const api = await caller();
    await api.shopping.generateFromLowStock();

    expect(await autoRows()).toHaveLength(1);
  });

  it("tops up its own row rather than writing a second one", async () => {
    const api = await caller();
    await api.shopping.generateFromLowStock();

    // Somebody edits it down to one litre, which no longer reaches the
    // minimum — so the next generate has something left to do.
    const [row] = await autoRows();
    await prisma.shoppingItem.update({
      where: { id: row?.id ?? "" },
      data: { quantity: 1 },
    });

    await api.shopping.generateFromLowStock();

    const rows = await autoRows();
    expect(rows).toHaveLength(1);
    expect(rows[0]?.quantity).toBe(3);
  });

  it("asks for less when the cupboard is part of the way there", async () => {
    await prisma.stockEntry.create({
      data: {
        productId: A.productId,
        quantity: 1,
        unit: "L",
        operationType: "PURCHASE",
        createdBy: A.userId,
      },
    });

    const api = await caller();
    await api.shopping.generateFromLowStock();

    const rows = await autoRows();
    expect(rows).toHaveLength(1);
    expect(rows[0]?.quantity).toBe(2);
  });
});
